"""Render saved classification replay; no network/model calls."""
import json,hashlib,html,statistics
from pathlib import Path
from collections import Counter
APP=Path(__file__).resolve().parents[1];OUT=APP/'results/routing-classifiers-2026-09-30'
old=json.loads((APP/'results/routing-gpt5-llm-jev-2026-09-29/comparison.json').read_text());native=json.loads((OUT/'native.json').read_text());auto=json.loads((OUT/'openrouter-decisions.json').read_text())
pairs={}
for r in json.loads((APP/'results/core18-gpt5-v2-2026-09-29/comparison.json').read_text())['rows']:pairs.setdefault(r['case'],{})[r['model']]=r
# Prior presentation schema is preserved as provenance; normalize only policy totals below.
prior=json.loads((APP/'results/routing-gpt5-llm-jev-2026-09-29/decisions.json').read_text())
policies=[]
def add(label,decisions,overhead=0,latency=None,kind='saved selection'):
 assert len(decisions)==18 and len({d['case'] for d in decisions})==18
 rows=[pairs[d['case']][d['selected']] for d in decisions];grades=Counter(r['review']['grade'] for r in rows);cost=sum(r['cost'] for r in rows)+overhead
 policies.append({'policy':label,'correct':grades['correct'],'partial':grades['partially_correct'],'incorrect':grades['incorrect'],'fully_correct_percent':100*grades['correct']/18,'replay_full_price_usd':cost,'overhead_usd':overhead,'saving_vs_gpt5_percent':100*(1-cost/.4562375),'cost_per_correct':cost/grades['correct'] if grades['correct'] else None,'selected':dict(Counter(d['selected'] for d in decisions)),'decision_seconds_mean':latency,'latency_scope':kind,'decisions':decisions})
for alias,label in [('eval-nano','Always nano'),('eval-5','Always GPT-5')]:add(label,[{'case':cid,'selected':alias} for cid in pairs])
for mode,label in [('llm','Nano LLM classifier'),('jev','JEV classifier')]:
 ds=prior[mode];add(label,ds,sum(x['cost'] for x in ds),statistics.mean(x['seconds'] for x in ds),'historical classifier network request')
prev_auto=json.loads((APP/'results/routing-gpt5-llm-jev-2026-09-29/openrouter-decisions.json').read_text());add('OpenRouter low',prev_auto['decisions'])
embed_cost=sum(x['estimated_cost'] for x in native['embedding_calls'])
for mode,label in [('keyword','Keyword rules + heuristic fallback'),('heuristic','Default heuristic'),('semantic','Semantic matching + heuristic fallback')]:
 ds=[d for d in native['decisions'] if d['method']==mode]
 add(label,ds,embed_cost if mode=='semantic' else 0,statistics.mean(x['seconds'] for x in ds),'local compute' if mode!='semantic' else 'embedding request + local match; setup separate')
add('OpenRouter medium',auto['decisions'])
summary={'policies':policies,'new_spend':{'embedding_estimate_usd':embed_cost,'openrouter_reported_usd':sum(x['probe_cost'] for x in auto['decisions']),'total_usd':embed_cost+sum(x['probe_cost'] for x in auto['decisions'])},'semantic_no_match_cases':[d['case'] for d in native['decisions'] if d['method']=='semantic' and d['cause']=='no_match_heuristic'],'semantic_setup_seconds':native['semantic_setup_seconds'],'versions':{'litellm':native['version'],'configuration_sha256':native['config_sha256']},'notes':['Saved accepted grades, not newly generated answers. Known development set, not held-out.','Full-price candidate replay estimates preserve M16 basis; no cache savings inferred.','Semantic cost includes route-index embeddings and queries; conservative one-batch allocation.','Medium selected nano in all 18 probes; task classifications and GPT-5 fallback candidates are in raw metadata. Do not infer an exhaustive tier membership list.','No production router was enabled. Native classifier methods executed in an isolated container using installed image.']}
(OUT/'summary.json').write_text(json.dumps(summary,indent=2))
lines=['# Routing classifier comparison — September 30, 2026','', 'All methods choose between the same saved nano/GPT-5 answers on payout-v2. Opening question only; chosen answer includes saved follow-ups. Production support unchanged.','', '| Policy | Correct / partial / incorrect | Fully correct | Replay cost including classification | Saving vs GPT-5 | Nano / GPT-5 |','|---|---|---:|---:|---:|---:|']
for p in policies:lines.append(f"| {p['policy']} | {p['correct']} / {p['partial']} / {p['incorrect']} | {p['fully_correct_percent']:.1f}% | ${p['replay_full_price_usd']:.6f} | {p['saving_vs_gpt5_percent']:.1f}% | {p['selected'].get('eval-nano',0)} / {p['selected'].get('eval-5',0)} |")
lines+=['','## What this adds','', '- Keyword rules: highest matched tier wins; collisions retained in native.json. Unmatched questions use the native heuristic.','- Default heuristic: native LiteLLM 1.102.1 defaults. SIMPLE maps to nano; MEDIUM/COMPLEX/REASONING map to GPT-5. Scores were not tuned.','- Semantic matching: native semantic keyword routing using text-embedding-3-small, 14 frozen journey examples, max similarity, threshold 0.5. Ten of 18 questions had no qualifying match and fell back to the heuristic. No API failures were converted into successful semantic results.','- OpenRouter medium: exact nano/GPT-5 allowlist and correct auto-router plugin, 16-token probes, all 18 selected nano. Generated probe text is not graded. This is not a general verdict about medium-tier routing.', '', '## Spend and timing','',f"New embedding estimate ${embed_cost:.8f}; OpenRouter provider-reported probe cost ${summary['new_spend']['openrouter_reported_usd']:.8f}; total ${summary['new_spend']['total_usd']:.8f}. Saved candidate costs above are replay estimates, not newly incurred spend.",'',f"Semantic index initialization {native['semantic_setup_seconds']:.3f}s, separate from per-question timing. Local heuristic/keyword compute, network classifier latency and completion-probe latency are different measurements; do not rank their timings as equivalent end-to-end answer latency.", '', '## Evidence and limitations','',*['- '+x for x in summary['notes']], '', '- Frozen settings: ../../eval/routing-final-v1/classifiers.json; source and config hashes in frozen-manifest.json/native.json. Configuration freeze is an artifact hash, not a git commit.','- Native source copied under native-source for reproducibility. No classifier rules or thresholds changed after observing the results.','- Comparison uses accepted mixed human/assistant grades from the existing baseline. Semantic result depends strongly on example coverage and the frozen threshold; it does not establish that semantic routing is intrinsically worse.']
editorial_note='Purpose: demonstrate how to evaluate model choice, classifier policy and routing granularity for a particular application, not prescribe a winner. These small diagnostic samples illustrate the decision process; representative fresh cases and repetitions are needed before a deployment recommendation. See the user-confirmed editorial framing in EVALUATION-SPEC.md and milestone M21.'
lines[2:2]=[editorial_note,'']
(OUT/'REPORT.md').write_text('\n'.join(lines)+'\n')
cost_note='JEV classification itself cost $0.003759, versus $0.005436 for the nano LLM classifier. The JEV route costs more overall ($0.266017 versus $0.249470) because it selected GPT-5 for 10 cases instead of 9. These are alternative classifiers; their costs are not added together.'
lines += ['', '## Classifier cost versus selected-model cost', '', cost_note]
(OUT/'REPORT.md').write_text('\n'.join(lines)+'\n')
e=html.escape
rows=''.join('<tr>'+''.join(f'<td>{e(str(x))}</td>' for x in [p['policy'],f"{p['correct']} / {p['partial']} / {p['incorrect']}",f"{p['fully_correct_percent']:.1f}%",f"${p['replay_full_price_usd']:.6f}",f"{p['saving_vs_gpt5_percent']:.1f}%",f"{p['selected'].get('eval-nano',0)} / {p['selected'].get('eval-5',0)}"] )+'</tr>' for p in policies)
(OUT/'comparison.html').write_text('<!doctype html><meta charset="utf-8"><title>Routing classifiers</title><style>body{font:16px system-ui;max-width:1200px;margin:40px auto;padding:20px;color:#182338}table{border-collapse:collapse;width:100%}td,th{padding:12px;border-bottom:1px solid #ccd;text-align:left}pre{white-space:pre-wrap;background:#f3f5f8;padding:18px}summary{cursor:pointer;padding:12px}</style><h1>Routing classifier comparison</h1><p><strong>How to read these results:</strong> '+e(editorial_note)+'</p><p>September 30 · 18 saved sessions · nano vs GPT-5 · offline replay</p><table><tr><th>Policy</th><th>Correct / partial / incorrect</th><th>Fully correct</th><th>Replay cost</th><th>Saving</th><th>Nano / GPT-5</th></tr>'+rows+'</table><p><b>Cost breakdown:</b> '+e(cost_note)+'</p><p>New spend: $'+f"{summary['new_spend']['total_usd']:.8f}"+'. Replay estimates above are not new charges.</p><details><summary>Method, costs and limitations</summary><pre>'+e('\n'.join(lines))+'</pre></details>'+''.join('<details><summary>'+e(p['policy'])+' — decisions</summary><pre>'+e(json.dumps(p['decisions'],indent=2))+'</pre></details>' for p in policies))
print('Rendered',len(policies),'policies')
